"""Refused values stay refused when copied from history or generated by a merge."""

from datetime import UTC, datetime
from types import SimpleNamespace
from unittest.mock import AsyncMock

import pytest
from fastapi import HTTPException

from server.core import pg
from server.memory import store
from server.memory.api.models_admin import MemoryConsolidateInput
from server.memory.api.models_crud import MemoryRestoreInput
from server.memory.app import (
    blacklist_guard,
    consolidate,
    namespace_rollback,
    restore,
    snapshot_rows,
)
from server.memory.domain.rollback import RollbackAction, RollbackPlan
from server.memory.store import MemoryRow, pg_memory


@pytest.fixture(params=[False, True], ids=["clickhouse", "postgres"])
def guarded(monkeypatch, request):
    monkeypatch.setattr(pg, "enabled", lambda: request.param)
    policy = {("o", "policy"): 4}
    monkeypatch.setattr(pg_memory, "policy_generations", AsyncMock(return_value=policy))
    monkeypatch.setattr(blacklist_guard, "_ensure_loaded", AsyncMock())
    monkeypatch.setattr(blacklist_guard, "note_hit", AsyncMock())
    monkeypatch.setattr(
        blacklist_guard,
        "_cache",
        [blacklist_guard.BlacklistPattern("p", "o", "n", "blocked", "substring", "namespace", "")],
    )
    return policy


@pytest.fixture(params=["substring", "stored_regex"])
def copy_pattern(monkeypatch, guarded, request):
    if request.param == "stored_regex":
        pattern = r'^"blocked"$'
        monkeypatch.setattr(
            blacklist_guard,
            "_cache",
            [
                blacklist_guard.BlacklistPattern(
                    "p",
                    "o",
                    "n",
                    pattern,
                    "regex",
                    "namespace",
                    "",
                    compiled=blacklist_guard.compile_regex(pattern),
                )
            ],
        )


def row(value="blocked", **kw):
    return MemoryRow(
        org="o",
        namespace="n",
        agent="a",
        memory_key="k",
        memory_type="semantic",
        user_id="-",
        session_id="-",
        pinned=False,
        expires_at=None,
        value=value,
        confidence=1,
        version=1,
        created_at=datetime.now(UTC).replace(tzinfo=None),
        memory_id="11111111-1111-1111-1111-111111111111",
        **kw,
    )


def restore_input():
    return MemoryRestoreInput(org="o", namespace="n", agent="a", memory_key="k")


async def test_plain_restore_refuses_before_memory_or_search_write(monkeypatch, guarded):
    existing = row(tombstoned_at=datetime.now(UTC).replace(tzinfo=None))
    written = AsyncMock()
    mirror = AsyncMock()
    monkeypatch.setattr(store, "insert_versions_over_heads", written)
    restored = store.build_memory_version_row(existing, tombstoned_at=None, version=2)
    with pytest.raises(HTTPException) as error:
        await restore._insert_restore(
            restore_input(), restored, existing, ch=object(), what="restore", mirror=mirror
        )
    assert error.value.status_code == 422 and error.value.detail["code"] == "BLACKLISTED"
    written.assert_not_awaited()
    mirror.assert_not_awaited()


async def test_undo_refuses_before_its_strict_audit_record(monkeypatch, guarded, copy_pattern):
    from server.observability import audit

    ledger = AsyncMock()
    written = AsyncMock()
    monkeypatch.setattr(audit, "emit_strict", ledger)
    monkeypatch.setattr(restore, "_status_before_retirement", AsyncMock(return_value="active"))
    monkeypatch.setattr(restore, "_insert_restore", written)
    with pytest.raises(HTTPException, match="422"):
        await restore._write_restore(restore_input(), row(status="superseded"), ch=object())
    ledger.assert_not_awaited()
    written.assert_not_awaited()


async def test_snapshot_checks_the_whole_batch_before_any_insert(monkeypatch, guarded):
    written = AsyncMock()
    monkeypatch.setattr(store, "insert_memory_versions", written)
    rows = [store.build_memory_version_row(row("allowed")), store.build_memory_version_row(row())]
    with pytest.raises(HTTPException, match="422"):
        await snapshot_rows.insert_version_rows(rows, ch=object())
    written.assert_not_awaited()


async def test_rollback_checks_later_batches_before_writing_the_first(
    monkeypatch, guarded, copy_pattern
):
    monkeypatch.setattr(namespace_rollback, "_INSERT_BATCH", 1)
    historical = [row("allowed"), row()]

    async def reinstated(org, namespace, actions, **kw):
        return [(historical[int(a.memory_key)], row("head")) for a in actions]

    monkeypatch.setattr(namespace_rollback, "_reinstated", reinstated)
    monkeypatch.setattr("server.embedding.get_embedder", lambda: SimpleNamespace(model_name="fake"))
    written = AsyncMock()
    monkeypatch.setattr(namespace_rollback, "_write", written)
    plan = RollbackPlan(
        reinstate=[
            RollbackAction(
                agent="a",
                user_id="-",
                session_id="-",
                memory_key=str(i),
                action="reinstate",
                version_from=2,
                version_to=1,
            )
            for i in range(2)
        ],
        remove=[],
    )
    applied = namespace_rollback.Applied()
    with pytest.raises(HTTPException, match="422"):
        await namespace_rollback.apply_rollback(
            "o",
            "n",
            plan,
            applied_at=datetime.now(UTC).replace(tzinfo=None),
            ch=object(),
            applied=applied,
        )
    written.assert_not_awaited()
    assert applied.reinstated == applied.removed == 0
    if pg.enabled():
        pg_memory.policy_generations.assert_awaited_once_with("o")


async def test_consolidation_refuses_generated_value_before_embedding(monkeypatch, guarded):
    embedder = SimpleNamespace(embed=AsyncMock(side_effect=RuntimeError("embedding was attempted")))
    target = AsyncMock()
    written = AsyncMock()
    monkeypatch.setattr(consolidate, "_summary_target", target)
    monkeypatch.setattr(store, "insert_versions_over_heads", written)
    with pytest.raises(consolidate._Unmerged) as error:
        await consolidate._write_canonical(
            object(),
            MemoryConsolidateInput(org="o", namespace="n", agent="a"),
            embedder,
            [],
            canonical_key="merged",
            canonical_value="blocked",
            now_naive=datetime.now(UTC),
            claimed=set(),
        )
    assert error.value.drop == "blacklisted"
    embedder.embed.assert_not_awaited()
    target.assert_not_awaited()
    written.assert_not_awaited()


@pytest.mark.parametrize("value,namespace", [("allowed", "n"), ("blocked", "another")])
async def test_allowed_restore_still_writes_and_binds_policy(
    monkeypatch, guarded, value, namespace
):
    existing = row(value, tombstoned_at=datetime.now(UTC).replace(tzinfo=None))
    restored = store.build_memory_version_row(existing, tombstoned_at=None, namespace=namespace)
    written = AsyncMock()
    monkeypatch.setattr(store, "insert_versions_over_heads", written)
    await restore._insert_restore(
        restore_input(), restored, existing, ch=object(), what="restore", mirror=AsyncMock()
    )
    written.assert_awaited_once()
    assert written.await_args.kwargs["policy"] == (guarded if pg.enabled() else {})


@pytest.mark.parametrize("copy_path", ["snapshot", "restore"])
async def test_a_changed_policy_refuses_the_postgres_commit(monkeypatch, copy_path):
    from server.memory.store import inserts, lifecycle, pg_publish

    monkeypatch.setattr(pg, "enabled", lambda: True)
    policy = {("o", "policy"): 4}
    existing = row("allowed")
    rows = [store.build_memory_version_row(existing, version=2)]
    called = []

    async def refuse(rows, **kw):
        called.append(kw["admission"])
        raise pg_memory.AdmissionMoved({("o", "policy"): 5})

    publish = AsyncMock()
    monkeypatch.setattr(pg_publish, "commit", refuse)
    monkeypatch.setattr(pg_publish, "publish", publish)
    with pytest.raises(pg_memory.AdmissionContendedError, match="policy changed"):
        if copy_path == "snapshot":
            await inserts.insert_memory_versions(rows, ch=object(), policy=policy)
        else:
            await lifecycle.insert_versions_over_heads(rows, [existing], ch=object(), policy=policy)
    assert len(called) == 1 and called[0].generations == policy
    publish.assert_not_awaited()


async def test_a_blocked_payload_does_not_create_namespace_or_grants(monkeypatch, guarded):
    from contextlib import asynccontextmanager

    from server.identity.api.models import (
        NamespaceRestoreInput,
        NamespaceSnapshotOutput,
    )
    from server.identity.app import namespace_snapshot as namespaces

    @asynccontextmanager
    async def lock(*args):
        yield

    ch = SimpleNamespace(query_one=AsyncMock(return_value=None), insert=AsyncMock())
    grant = AsyncMock()
    monkeypatch.setattr(namespaces, "account_change", lock)
    monkeypatch.setattr(namespaces, "get_client", lambda: ch)
    monkeypatch.setattr(namespaces._registry, "resolve_subject", lambda: "owner")
    monkeypatch.setattr(namespaces._registry, "insert_admin_grant", grant)
    monkeypatch.setattr(namespaces.registration, "refused_as_in_use", AsyncMock(return_value=False))
    monkeypatch.setattr(pg_memory, "erased_ids", AsyncMock(return_value=set()))
    payload = NamespaceSnapshotOutput(
        snapshot_id="22222222-2222-2222-2222-222222222222",
        org="o",
        source_namespace="source",
        created_at=datetime.now(UTC),
        memory_count=2,
        type_count=0,
        grant_count=0,
        audit_tail_count=0,
        include_embeddings=False,
        memories=[
            namespaces.snapshot_memory_row(store.build_memory_version_row(row(value)))
            for value in ["allowed", "blocked"]
        ],
        types=[],
        grants=[],
        audit_tail=[],
    )
    with pytest.raises(HTTPException, match="422"):
        await namespaces.handle_namespace_restore(
            NamespaceRestoreInput(org="o", target_namespace="n", payload=payload)
        )
    ch.insert.assert_not_awaited()
    grant.assert_not_awaited()


@pytest.mark.parametrize("guarded", [False], indirect=True)
@pytest.mark.parametrize("repair", ["undelete", "undo"])
async def test_a_restore_retry_cannot_repair_a_blacklisted_search_document(
    monkeypatch, guarded, repair
):
    from contextlib import asynccontextmanager

    @asynccontextmanager
    async def lock(*args):
        yield

    existing = row(status="active")
    mirror = AsyncMock()
    monkeypatch.setattr(restore, "_read_restorable", AsyncMock(return_value=existing))
    monkeypatch.setattr(restore, "_restore_embedding_mirror", mirror)
    monkeypatch.setattr(restore, "_unsupersede", mirror)
    monkeypatch.setattr(restore, "_undelete_left_unmirrored", AsyncMock(return_value=True))
    monkeypatch.setattr(restore, "_landed_late", AsyncMock(return_value=True))
    monkeypatch.setattr(restore, "_key_lock", lock)
    monkeypatch.setattr(restore, "_reopen_facts", AsyncMock())
    with pytest.raises(HTTPException, match="422"):
        if repair == "undo":
            await restore._restore_superseded(restore_input(), ch=object())
        else:
            await restore._restore_live(restore_input(), {"memory_type": "semantic"}, ch=object())
    mirror.assert_not_awaited()
